<script lang="ts">
  import QRCode from 'qrcode';
  import { api, query } from './api';
  import type { User, Data } from './types';
  import Receipt from './Receipt.svelte';
  export let user: User; export let view: string;
  let data: Data = {}, items: Data[] = [], error = '', loading = false, invoice: Data | null = null, date = '', period = '', page = 1, more = false, qr = '', profile: Data = {}, oldPassword = '', newPassword = '', msg = '';
  let lastView = '';
  const rp = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(n || 0);
  $: if (view !== lastView) { lastView = view; if (typeof window !== 'undefined') load(); }
  async function load(next = false) { loading = true; error = ''; try {
    if (view === 'dashboard') { data = await api(user.role === 'KASIR' ? '/kasir/dashboard' : user.role === 'ANGGOTA' ? '/saya/dashboard' : '/admin/dashboard'); items = data.terakhir || []; }
    if (view === 'riwayat') { const p = next ? page + 1 : 1; data = await api(user.role === 'KASIR' ? '/kasir/riwayat' + query({ tanggal: date }) : '/saya/transaksi' + query({ periode: period, page: p, size: 30 })); items = next ? [...items, ...data.items] : data.items; page = p; more = data.ada_lagi === true; }
    if (view === 'kartu' && user.nik) qr = await QRCode.toDataURL(user.nik, { errorCorrectionLevel: 'H', margin: 2, width: 320 });
    if (view === 'profil') profile = await api('/profil');
  } catch (e) { error = (e as Error).message; } finally { loading = false; } }
  async function detail(no: string) { try { invoice = await api((user.role === 'KASIR' ? '/faktur/' : user.role === 'ADMIN' ? '/admin/faktur/' : '/saya/transaksi/') + encodeURIComponent(no)); } catch (e) { error = (e as Error).message; } }
  async function saveProfile() { try { await api('/profil', { method: 'PUT', body: { nama: profile.nama, telepon: profile.telepon || '', email: profile.email || '' } }); msg = 'Profil berhasil disimpan.'; } catch (e) { error = (e as Error).message; } }
  async function photo(e: Event) { const file = (e.currentTarget as HTMLInputElement).files?.[0]; if (!file) return; try { await api('/profil/foto', { method: 'PUT', body: file, headers: { 'Content-Type': 'application/octet-stream' } }); msg = 'Foto profil diperbarui.'; } catch (e) { error = (e as Error).message; } }
  async function password() { try { await api('/auth/ganti-password', { method: 'POST', body: { password_lama: oldPassword, password_baru: newPassword } }); localStorage.removeItem('kopkar_web_tokens'); location.reload(); } catch (e) { error = (e as Error).message; } }
</script>
{#if error}<div class="error" role="alert">{error}</div>{/if}{#if msg}<div class="notice">{msg}</div>{/if}{#if loading}<p class="muted">Memuat data…</p>{/if}
{#if view === 'dashboard'}
  {#if data.belanja_demo}<div class="notice">MODE DEMO · Belanja mandiri hanya simulasi dan tidak tersimpan.</div>{/if}
  {#if data.periode_terbuka === false}<div class="notice">{data.periode_pesan || data.pesan || 'Periode belum terbuka.'}</div>{/if}
  <div class="welcome"><div><p class="eyebrow light">KOPKAR KUSUMA LESTARI</p><h2>Selamat datang,<br/>{user.nama.split(' ')[0]}.</h2><p>Semua kebutuhan koperasi Anda, dalam satu tempat.</p></div><div class="welcome-mark">✳</div></div>
  <div class="section-heading"><div><p class="eyebrow">RINGKASAN</p><h2>{user.role === 'ANGGOTA' ? 'Belanja Anda' : 'Aktivitas hari ini'}</h2></div><span class="muted">{data.tanggal || data.ringkasan?.dari || ''}</span></div>
  <div class="stats"><div class="stat"><span>{user.role === 'ANGGOTA' ? 'Belanja periode ini' : 'Total penjualan'}</span><strong>{rp(data.ringkasan?.belanja_periode ?? data.ringkasan?.total)}</strong></div><div class="stat"><span>{user.role === 'ANGGOTA' ? 'Sisa limit' : 'Transaksi'}</span><strong>{user.role === 'ANGGOTA' ? data.ringkasan?.sisa_limit == null ? 'Tidak dibatasi' : rp(data.ringkasan.sisa_limit) : data.ringkasan?.jumlah ?? 0}</strong></div><div class="stat"><span>{user.role === 'ANGGOTA' ? 'Limit belanja' : 'Penjualan kredit'}</span><strong>{user.role === 'ANGGOTA' && !data.ringkasan?.limit ? 'Tidak dibatasi' : rp(user.role === 'ANGGOTA' ? data.ringkasan?.limit : data.ringkasan?.kredit)}</strong></div></div>
  {#if items.length}<div class="panel"><h3>Transaksi terbaru</h3>{#each items as t}<button class="list-button horizontal" on:click={() => detail(t.no_transaksi)}><span><strong>{t.nama_pelanggan || t.no_transaksi}</strong><small>{t.no_transaksi} · {t.jam || t.tanggal}</small></span><strong>{rp(t.total)} →</strong></button>{/each}</div>{/if}
{:else if view === 'riwayat'}<div class="panel"><div class="section-heading"><div><p class="eyebrow">TRANSAKSI</p><h2>Riwayat belanja</h2></div></div><form class="search" on:submit|preventDefault={() => load()}>{#if user.role === 'KASIR'}<input type="date" bind:value={date} aria-label="Tanggal"/>{:else}<input type="number" bind:value={period} placeholder="Periode, contoh 202611" aria-label="Periode"/>{/if}<button>Cari</button></form>{#each items as t}<button class="list-button horizontal" on:click={() => detail(t.no_transaksi)}><span><strong>{t.nama_pelanggan || t.no_transaksi}</strong><small>{t.no_transaksi} · {t.tanggal || ''} {t.jam || ''}</small></span><strong>{rp(t.total)} →</strong></button>{:else}<p class="empty">Belum ada transaksi.</p>{/each}{#if more}<button class="secondary wide" on:click={() => load(true)}>Muat lebih banyak</button>{/if}</div>
{:else if view === 'kartu'}<div class="member-card"><p class="eyebrow light">KARTU ANGGOTA DIGITAL</p><h2>{user.nama}</h2><p>{user.nik}</p>{#if qr}<img src={qr} alt="QR kartu anggota"/>{/if}<small>Tunjukkan kode ini kepada kasir.</small></div>
{:else if view === 'profil'}<div class="form-grid"><section class="panel"><p class="eyebrow">AKUN ANDA</p><h2>Profil</h2><form on:submit|preventDefault={saveProfile}><label>Nama<input bind:value={profile.nama} required/></label><label>Telepon<input bind:value={profile.telepon}/></label><label>Email<input type="email" bind:value={profile.email}/></label><button class="primary">Simpan profil</button></form><label>Foto profil (JPEG/PNG, maks. 1 MB)<input type="file" accept="image/jpeg,image/png" on:change={photo}/></label><button class="secondary" on:click={async () => { try { await api('/profil/foto', {method:'DELETE'}); msg = 'Foto dihapus.'; } catch(e) { error = (e as Error).message; } }}>Hapus foto</button></section><section class="panel"><p class="eyebrow">KEAMANAN</p><h2>Ganti password</h2><form on:submit|preventDefault={password}><label>Password lama<input type="password" bind:value={oldPassword} required/></label><label>Password baru<input type="password" bind:value={newPassword} required/></label><p class="muted">Anda perlu login kembali setelah mengganti password.</p><button class="secondary">Ganti password</button></form></section></div>{/if}
{#if invoice}<Receipt {invoice} close={() => invoice = null}/>{/if}
